    12→import { toast } from "sonner";
    13→import type { Result } from "@/pages/Index";
    14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
    15→
    16→// Sub-components
    17→import CandidateSummary from "@/components/candidate/CandidateSummary";
    18→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
    19→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
    20→import EducationPanel from "@/components/candidate/EducationPanel";
    21→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
    22→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
    23→import AINudgePanel from "@/components/candidate/AINudgePanel";
