   218→                  </TooltipTrigger>
   219→                  <TooltipContent>{r.candidate_email || "No email"}</TooltipContent>
   220→                </Tooltip>
   221→
   222→                {/* Download */}
   223→                <Tooltip>
   224→                  <TooltipTrigger asChild>
   225→                    {r.file_path ? (
   226→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
   227→                        <FileText className="h-3.5 w-3.5" />
   228→                      </Button>
   229→                    ) : (
   230→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   231→                        <FileText className="h-3.5 w-3.5" />
   232→                      </Button>
   233→                    )}
   234→                  </TooltipTrigger>
   235→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
   236→                </Tooltip>
   237→
   238→                {/* Archive */}
   239→                <Tooltip>
   240→                  <TooltipTrigger asChild>
   241→                    <Button
   242→                      variant="ghost" size="icon"
   243→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
   244→                      onClick={() => onDismiss(r.resume_id)}
   245→                    >
   246→                      <Archive className="h-3.5 w-3.5" />
   247→                    </Button>
   248→                  </TooltipTrigger>
   249→                  <TooltipContent>Archive candidate</TooltipContent>
   250→                </Tooltip>
   251→              </TooltipProvider>
   252→
   253→              {!r.pending && (
   254→                <CollapsibleTrigger asChild>
   255→                  <Button variant="ghost" size="icon" className="h-7 w-7">
   256→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
   257→                  </Button>
   258→                </CollapsibleTrigger>
   259→              )}
   260→            </div>
   261→          </TableCell>
   262→        </TableRow>
   263→
   264→        {/* Expanded Detail — New Layout */}
   265→        {!r.pending && (
   266→          <CollapsibleContent asChild>
   267→            <TableRow className="bg-muted/30 hover:bg-muted/30">
   268→              <TableCell colSpan={6} className="p-5">
   269→                <div className="space-y-4">
   270→                  {/* 1. AI Summary */}
   271→                  <CandidateSummary result={r} />
   272→
   273→                  {/* 2. Stage Tracker */}
   274→                  {onStageChange && (
   275→                    <StageTracker
   276→                      currentStage={currentStage || "applied"}
   277→                      updatedAt={stageUpdatedAt}
   278→                      onStageChange={(stage) => onStageChange(r.resume_id, stage)}
   279→                    />
   280→                  )}
   281→
   282→                  {/* 3. Skills Detail | Experience | Education — 3 columns */}
   283→                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
   284→                    <SkillsDetailPanel result={r} />
   285→                    <ExperiencePanel parsedJson={r.parsed_json} />
   286→                    <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
   287→                  </div>
   288→
   289→                  {/* 4. JD Aligned — full width */}
   290→                  <JDAlignedPanel result={r} />
   291→
   292→                  {/* 5. Strengths & Gaps — full width */}
   293→                  <StrengthsGapsPanel result={r} />
   294→
   295→                  {/* 6. AI Nudge + Rewrite JD */}
   296→                  <AINudgePanel result={r} onRewriteJd={onRewriteJd} />
   297→
   298→                  {/* 7. Interview Questions — collapsible */}
   299→                  <InterviewQuestionsPanel result={r} />
   300→                </div>
   301→              </TableCell>
   302→            </TableRow>
   303→          </CollapsibleContent>
   304→        )}
   305→      </>
   306→    </Collapsible>
   307→
   308→    {r.candidate_email && (
   309→      <EmailOutreachDialog
   310→        open={emailDialogOpen}
   311→        onOpenChange={setEmailDialogOpen}
   312→        candidateName={r.candidate_name || r.filename}
   313→        candidateEmail={r.candidate_email}
   314→        jobTitle={jobTitle || "Open Position"}
   315→        matchScore={Math.round(r.overall_score ?? 0)}
   316→        resumeId={r.resume_id}
   317→        jobId={r.id}
   318→      />
   319→    )}
   320→    </>
   321→  );
   322→};
   323→
   324→export default CandidateRow;
   325→

