     1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
     2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
     3→import { extractText } from "https://esm.sh/unpdf@0.12.1";
     4→
     5→const corsHeaders = {
     6→  "Access-Control-Allow-Origin": "*",
     7→  "Access-Control-Allow-Headers":
     8→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
     9→};
    10→
    11→const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
    12→const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    13→const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    14→const CURRENT_PARSE_VERSION = "v2";
    15→
    16→// ── Fuzzy/semantic skill matching utilities ──────────────────
    17→const SKILL_SYNONYMS: Record<string, string[]> = {
    18→  "javascript": ["js", "ecmascript", "es6", "es2015"],
    19→  "typescript": ["ts"],
    20→  "python": ["py", "python3"],
    21→  "react": ["reactjs", "react.js"],
    22→  "angular": ["angularjs", "angular.js"],
    23→  "vue": ["vuejs", "vue.js"],
    24→  "node": ["nodejs", "node.js"],
    25→  "postgres": ["postgresql", "psql", "pg"],
    26→  "mongodb": ["mongo"],
    27→  "kubernetes": ["k8s"],
    28→  "docker": ["containerization", "containers"],
    29→  "aws": ["amazon web services"],
    30→  "gcp": ["google cloud", "google cloud platform"],
    31→  "azure": ["microsoft azure"],
    32→  "ci/cd": ["cicd", "ci cd", "continuous integration", "continuous deployment"],
    33→  "machine learning": ["ml"],
    34→  "deep learning": ["dl"],
    35→  "natural language processing": ["nlp"],
    36→  "graphql": ["gql"],
    37→  "rest": ["restful", "rest api", "restful api"],
    38→  "sql": ["structured query language"],
    39→  "nosql": ["no-sql"],
    40→  "html": ["html5"],
    41→  "css": ["css3", "stylesheets"],
    42→  "sass": ["scss"],
    43→  "c#": ["csharp", "c sharp"],
    44→  "c++": ["cpp"],
    45→  "objective-c": ["objc"],
    46→  "swift": ["swiftui"],
    47→  "ruby": ["rb"],
    48→  "ruby on rails": ["rails", "ror"],
    49→  "spring": ["spring boot", "springboot"],
    50→  ".net": ["dotnet", "dot net"],
    51→  "terraform": ["tf"],
    52→  "elasticsearch": ["elastic", "es"],
    53→  "redis": ["redis cache"],
    54→  "kafka": ["apache kafka"],
    55→  "rabbitmq": ["rabbit mq"],
    56→  "figma": ["figma design"],
    57→  "photoshop": ["adobe photoshop"],
    58→  "agile": ["scrum", "kanban"],
    59→  "devops": ["dev ops"],
    60→  "data science": ["data analytics", "data analysis"],
    61→};
    62→
    63→// Build reverse lookup: synonym -> canonical
    64→const synonymToCanonical = new Map<string, string>();
    65→for (const [canonical, synonyms] of Object.entries(SKILL_SYNONYMS)) {
    66→  synonymToCanonical.set(canonical, canonical);
    67→  for (const syn of synonyms) {
    68→    synonymToCanonical.set(syn, canonical);
    69→  }
    70→}
    71→
    72→function normalizeSkill(skill: string): string {
    73→  const lower = skill.toLowerCase().trim()
    74→    .replace(/[.\-\/]/g, '')  // remove dots, hyphens, slashes for comparison
    75→    .replace(/\s+/g, ' ');    // normalize whitespace
    76→  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
    77→}
    78→
    79→function tokenize(term: string): string[] {
    80→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
    81→}
    82→
    83→function tokenOverlap(a: string, b: string): number {
    84→  const tokensA = tokenize(a);
    85→  const tokensB = tokenize(b);
    86→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
    87→  const setB = new Set(tokensB);
    88→  const matched = tokensA.filter(t => setB.has(t)).length;
    89→  return matched / Math.max(tokensA.length, tokensB.length);
    90→}
    91→
    92→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
    93→  const normalizedJd = normalizeSkill(jdTerm);
    94→  for (const rt of resumeTerms) {
    95→    const normalizedResume = normalizeSkill(rt);
    96→    // Exact match after normalization
    97→    if (normalizedJd === normalizedResume) return true;
    98→    // Substring containment (original behavior)
    99→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
   100→    // Token overlap (e.g. "machine learning" vs "ml engineering" after synonym expansion)
   101→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
   102→  }
   103→  return false;
   104→}
   105→
   106→function extractResumeTerms(parsedJson: any): string[] {
   107→  const p = parsedJson || {};
   108→  const resumeSkills = (p.skills_with_evidence || []).map((s: any) =>
   109→    (typeof s === 'string' ? s : s.skill || s.name || '').toLowerCase()
   110→  );
   111→  const resumeTools = (p.tools || []).map((t: string) => t.toLowerCase());
   112→  // Also include domain experience and role titles for broader matching
   113→  const domains = p.domain_experience ? [p.domain_experience.toLowerCase()] : [];
   114→  const roleTitles = (p.roles_with_dates || []).map((r: any) => (r.title || r.role || '').toLowerCase());
   115→  return [...resumeSkills, ...resumeTools, ...domains, ...roleTitles].filter(Boolean);
   116→}
   117→
   118→serve(async (req) => {
   119→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
   120→
   121→  try {
   122→    const authHeader = req.headers.get("Authorization");
   123→    if (!authHeader) throw new Error("No auth header");
   124→
   125→    const token = authHeader.replace("Bearer ", "");
   126→    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
   127→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
   128→      global: { headers: { Authorization: authHeader } },
   129→    });
   130→    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
   131→    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
   132→    const user = { id: claimsData.claims.sub as string };
   133→
   134→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
   135→
   136→    // Fetch ranking config
   137→    const { data: rankingConfig } = await supabase.from("ranking_config").select("*").limit(1).single();
   138→    const cfg = {
   139→      model: rankingConfig?.model || "gpt-4o-mini",
   140→      temperature: rankingConfig?.temperature ?? 0.2,
   141→      max_resume_chars: rankingConfig?.max_resume_chars ?? 4000,
   142→      num_interview_questions: rankingConfig?.num_interview_questions ?? 5,
   143→    };
   144→    const resumeParsePrompt: string | null = rankingConfig?.resume_parse_prompt || null;
   145→    const deepScoringPrompt: string | null = rankingConfig?.deep_scoring_prompt || null;
   146→
   147→    const { job_id, resume_ids } = await req.json();
   148→    if (!job_id) throw new Error("Missing job_id");
   149→
   150→    // Rate limit: 3 jobs/min
   151→    const oneMinAgo = new Date(Date.now() - 60000).toISOString();
   152→    const { count } = await supabase
   153→      .from("jobs")
   154→      .select("id", { count: "exact", head: true })
   155→      .eq("user_id", user.id)
   156→      .gte("created_at", oneMinAgo);
   157→    if ((count ?? 0) > 3) {
   158→      return new Response(JSON.stringify({ error: "Rate limit: max 3 jobs per minute" }), {
   159→        status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
   160→      });
   161→    }
   162→
   163→    // Fetch job with JD analysis
   164→    const { data: job } = await supabase.from("jobs").select("*").eq("id", job_id).single();
   165→    if (!job) throw new Error("Job not found");
   166→    if (job.user_id !== user.id) throw new Error("Unauthorized");
   167→
   168→    const jdAnalysis = job.jd_analysis_json;
   169→    const dynamicWeights = job.dynamic_weights_json;
   170→    const jdEmbedding = job.jd_embedding;
   171→
   172→    if (!jdAnalysis || !dynamicWeights) {
   173→      return new Response(
   174→        JSON.stringify({ error: "JD analysis required. Please analyze the job description first." }),
