   808→// ── PDF text extraction fallback ───────────────────────────────
   809→function extractPdfText(bytes: Uint8Array): string {
   810→  const raw = new TextDecoder("latin1").decode(bytes);
   811→  const textChunks: string[] = [];
   812→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
   813→  let block;
   814→  while ((block = btEtRegex.exec(raw)) !== null) {
   815→    const parenRegex = /\(([^)]*)\)/g;
   816→    let match;
   817→    while ((match = parenRegex.exec(block[1])) !== null) {
   818→      const decoded = match[1]
   819→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
   820→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
   821→      if (decoded.trim()) textChunks.push(decoded);
   822→    }
   823→  }
   824→  if (textChunks.join(" ").trim().length < 200) {
   825→    const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
   826→    let sm;
   827→    while ((sm = streamRegex.exec(raw)) !== null) {
   828→      const readable = sm[1].replace(/[^\x20-\x7E\n\r\t]/g, " ").replace(/\s+/g, " ").trim();
   829→      if (readable.length > 50) textChunks.push(readable);
   830→    }
   831→  }
   832→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 10000);
   833→}
